import{z as B,x as C,o as A,c as o,q as l,j as i,D as e,d as r,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"证书透明 CT","description":"","frontmatter":{"title":"证书透明 CT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/certificate-transparency.md","filePath":"cs/certificate-transparency.md","lastUpdated":1791413859000}'),d={name:"cs/certificate-transparency.md"};function p(c,a,T,m,D,h){const t=C("Mermaid");return A(),o("div",null,[a[2]||(a[2]=l('<h1 id="证书透明-ct" tabindex="-1">证书透明 CT <a class="header-anchor" href="#证书透明-ct" aria-label="Permalink to &quot;证书透明 CT&quot;">​</a></h1><div class="epigraph"><p>验证告诉你「这条链在数学上连到锚」；透明日志告诉你「这张证书曾经被公开过」。误签与流氓中间要在公众视野里被发现，而不是只在受害主机的缓存里。</p><footer>—— RFC 6962；Laurie, Certificate Transparency, CACM；对照 Merkle 树课</footer></div><p>上一课<a href="/cs/tls-cert-chain-validation">链验证</a>保证路径到锚。缺口是<strong>锚或中间被骗签了一张不该存在的证</strong>：验证仍通过。CT 用可公开审计的 Merkle 日志钉「签发事件」。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CA 会误签。浏览器要求叶证书带 SCT，证明已提交日志。<span class="marginnote">SCT 翻译过来是「签发时间证明」，本质是一张收据：日志收到证书后签名承诺「我会把它记入公开账本」。浏览器把「出示这张收据」设为上桌门槛——没在公开账本登记过的证，握手直接不给过。</span>包含证明走<a href="/cs/commitment-merkle-tree">Merkle</a>路径；监控者看域名。缺口是「可发现」不是「不能签发」——CT 是威慑与事后，不是吊销本身。</p><h3 id="日志也会撒谎" tabindex="-1">日志也会撒谎 <a class="header-anchor" href="#日志也会撒谎" aria-label="Permalink to &quot;日志也会撒谎&quot;">​</a></h3><p>多日志、八卦协议削弱单日志作弊。客户端抽查包含证明，不把日志当新的根 CA。<span class="marginnote">「日志也会撒谎」指两种玩法：收了证书不给记（账本里没有你那份），或展示两本不同的账。对策是结构性的——日志只许追加、定期公布带签名的树头（整本账的摘要），任何人拿 SCT 都能索要「包含证明」核对那笔记真在账里；多本账之间再八卦对账，两本账对不上本身就是作弊证据。</span></p>',8)),(A(),i(n,null,{default:e(()=>[s(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E6%96%B0%E8%AF%81%E4%B9%A6%E5%93%88%E5%B8%8C%E5%8F%AA%E8%BF%BD%E5%8A%A0%E8%BF%9B%20Merkle%20%E6%A0%91%22%5D%20--%3E%20HEAD%5B%22%E6%97%A5%E5%BF%97%E5%AE%9A%E6%9C%9F%E5%85%AC%E5%B8%83%E7%AD%BE%E5%90%8D%E6%A0%91%E5%A4%B4%22%5D%0A%20%20HEAD%20--%3E%20INC%7B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%8B%BF%20SCT%20%E7%B4%A2%E8%A6%81%E5%8C%85%E5%90%AB%E8%AF%81%E6%98%8E%22%7D%0A%20%20INC%20--%3E%7C%22%E8%B7%AF%E5%BE%84%E5%AF%B9%E4%B8%8D%E4%B8%8A%E6%A0%91%E5%A4%B4%22%7C%20LIE%5B%22%E7%A7%81%E5%90%9E%E8%AE%B0%E5%BD%95%E8%A2%AB%E5%9D%90%E5%AE%9E%EF%BC%8C%E5%8F%AF%E5%85%AC%E5%BC%80%E6%8C%87%E8%AE%A4%22%5D%0A%20%20INC%20--%3E%7C%22%E8%B7%AF%E5%BE%84%E5%AF%B9%E4%B8%8A%22%7C%20PUB%5B%22%E7%AD%BE%E5%8F%91%E7%A1%AE%E5%B7%B2%E5%85%AC%E5%BC%80%22%5D%0A%20%20S1%5B%22%E6%97%A5%E5%BF%97%20A%20%E7%9A%84%E6%A0%91%E5%A4%B4%22%5D%20--%3E%20GOS%5B%22%E8%B7%A8%E6%97%A5%E5%BF%97%E5%85%AB%E5%8D%A6%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20S2%5B%22%E6%97%A5%E5%BF%97%20B%20%E7%9A%84%E6%A0%91%E5%A4%B4%22%5D%20--%3E%20GOS%0A%20%20GOS%20--%3E%7C%22%E8%A7%86%E5%9B%BE%E5%88%86%E8%A3%82%22%7C%20LIAR2%5B%22%E5%8D%95%E6%97%A5%E5%BF%97%E4%BD%9C%E5%BC%8A%E6%9A%B4%E9%9C%B2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"RFC 6962 / 9162。Google 的 CT 政策推动了部署。本课不写如何向日志灌垃圾的操作。")],-1)),a[4]||(a[4]=E("h2",{id:"方法",tabindex:"-1"},[r("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[5]||(a[5]=E("p",null,"画：CA 预提交→日志返回 SCT→握手带 SCT→客户端可验包含。对照 OCSP：吊销是「这张已作废」；CT 是「这张曾出现」。二者一起才接近生命周期。",-1)),(A(),i(n,null,{default:e(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CA%5B%22CA%20%E7%AD%BE%E5%8F%91%22%5D%20--%3E%20LOG%5B%22CT%20%E6%97%A5%E5%BF%97%20Merkle%22%5D%0A%20%20LOG%20--%3E%20SCT%5B%22SCT%22%5D%0A%20%20SCT%20--%3E%20TLS%5B%22%E6%8F%A1%E6%89%8B%E6%90%BA%E5%B8%A6%22%5D%0A%20%20LOG%20--%3E%20MON%5B%22%E5%9F%9F%E5%90%8D%E7%9B%91%E6%8E%A7%E5%8F%91%E7%8E%B0%E8%AF%AF%E7%AD%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公钥基础设施的社会层：透明让错误可被点名。它不替代名字约束，不替代 ACME 对域名控制权的证明。下一课 ACME：自动化申请如何证明「我控制该名」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有日志操作者列成名单。ACME 下一课从人工 CSR 换成自动化挑战。</p><p><span class="marginnote">常见误区：把「进了 CT 日志」当成「这张证更安全」。CT 不阻止 CA 误签、也不作废任何证书，它只保证「签过就会留痕，域主能发现」。发现误签之后，处置仍要走吊销（OCSP/CRL）与浏览器惩罚 CA——发现与处置是两步，缺一不可。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链验证通过仍可能是误签；CT 让签发可审计。</li><li>SCT + Merkle 包含；监控看自己的名。</li><li>发现 ≠ 吊销；OCSP/CRL 仍要。</li><li>下一课 ACME：自动证明域名控制。</li><li>出处：RFC 6962；Laurie, CACM；Merkle, 1980。</li></ul>',7))])}const S=B(d,[["render",p]]);export{f as __pageData,S as default};
